    pub(crate) async fn emit_turn_started(&self, turn_context: &TurnContext) {
        let event = TurnStartedEvent {
            turn_id: turn_context.sub_id.clone(),
            root_turn_id: Some(
                turn_context
                    .turn_metadata_state
                    .root_turn_id()
                    .unwrap_or_else(|| turn_context.sub_id.clone()),
            ),
